from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform divider separating equally sized panels.
    split = None
    for c in range(w):
        if 2 * c + 1 == w and all(grid[r][c] == grid[0][c] for r in range(h)):
            split = ("v", c)
            break
    if split is None:
        for r in range(h):
            if 2 * r + 1 == h and all(x == grid[r][0] for x in grid[r]):
                split = ("h", r)
                break

    if split[0] == "v":
        c = split[1]
        a = [row[:c] for row in grid]
        b = [row[c + 1:] for row in grid]
    else:
        r = split[1]
        a, b = grid[:r], grid[r + 1:]

    shared = set(x for row in a for x in row) & set(x for row in b for x in row)
    base = max(shared, key=lambda x: sum(v == x for row in a + b for v in row))

    return [
        [3 if a[i][j] == b[i][j] == base else base
         for j in range(len(a[0]))]
        for i in range(len(a))
    ]
